import { BrowserRouter, Routes, Route } from "react-router-dom";
import { AuthProvider } from "./contexte/ContexteAuth"; // ✅ corrigé
import { ProviderPanier } from "./contexte/ContextePanier";
import BarreNavigation from "./components/layout/BarreNavigation";
import PiedDePage from "./components/layout/PiedDePage";
import { useAuth } from "./hooks/useAuth";
import { usePanier } from "./hooks/usePanier";

import Accueil from "./pages/Accueil";
import Catalogue from "./pages/Catalogue";
import DetailProduit from "./pages/DetailProduit";
import Panier from "./pages/Panier";
import MesCommandes from "./pages/MesCommandes";
import Connexion from "./pages/Connexion";
import Inscription from "./pages/Inscription";
import Profil from "./pages/Profil";


// 🔝 TOPBAR
function Topbar() {
  const { utilisateur } = useAuth();
  const { totalArticles } = usePanier();
  const initiale = utilisateur?.nom?.charAt(0).toUpperCase() || "U";

  return (
    <header style={styles.topbar}>

      {/* Recherche */}
      <div style={styles.searchBox}>
        <span>🔍</span>
        <input
          placeholder="Rechercher un produit..."
          style={styles.searchInput}
        />
      </div>

      {/* Notifications */}
      <div style={styles.iconBox}>
        🔔
        <span style={styles.badge}>2</span>
      </div>

      {/* Panier */}
      <div style={styles.iconBox}>
        🛒
        {totalArticles > 0 && (
          <span style={styles.badge}>{totalArticles}</span>
        )}
      </div>

      {/* Utilisateur */}
      <div style={styles.userBox}>
        <div style={styles.avatar}>{initiale}</div>
        <div>
          <div style={styles.smallText}>Bonjour,</div>
          <div style={styles.username}>
            {utilisateur?.nom || "Invité"}
          </div>
        </div>
      </div>
    </header>
  );
}


// 🧱 LAYOUT
function Layout() {
  return (
    <div style={{ display: "flex" }}>
      <BarreNavigation />

      <div style={styles.mainContainer}>
        <Topbar />

        <main style={styles.main}>
          <Routes>
            <Route path="/" element={<Accueil />} />
            <Route path="/catalogue" element={<Catalogue />} />
            <Route path="/produit/:id" element={<DetailProduit />} />
            <Route path="/panier" element={<Panier />} />
            <Route path="/mes-commandes" element={<MesCommandes />} />
            <Route path="/connexion" element={<Connexion />} />
            <Route path="/inscription" element={<Inscription />} />
            <Route path="/profil" element={<Profil />} />
          </Routes>
        </main>

        <PiedDePage />
      </div>
    </div>
  );
}


// 🚀 APP
export default function App() {
  return (
    <AuthProvider> {/* ✅ corrigé */}
      <ProviderPanier>
        <BrowserRouter>
          <Layout />
        </BrowserRouter>
      </ProviderPanier>
    </AuthProvider>
  );
}


// 🎨 STYLES
const styles = {
  topbar: {
    position: "fixed",
    top: 0,
    left: "220px",
    right: 0,
    height: "60px",
    background: "white",
    borderBottom: "1px solid #eee",
    display: "flex",
    alignItems: "center",
    padding: "0 25px",
    gap: "15px",
    zIndex: 100,
  },

  searchBox: {
    flex: 1,
    display: "flex",
    alignItems: "center",
    gap: "8px",
    background: "#f1f3f5",
    padding: "8px 12px",
    borderRadius: "8px",
  },

  searchInput: {
    border: "none",
    outline: "none",
    background: "none",
    width: "100%",
  },

  iconBox: {
    position: "relative",
    width: "36px",
    height: "36px",
    border: "1px solid #eee",
    borderRadius: "8px",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    cursor: "pointer",
  },

  badge: {
    position: "absolute",
    top: "-5px",
    right: "-5px",
    background: "#E03131",
    color: "white",
    fontSize: "10px",
    width: "16px",
    height: "16px",
    borderRadius: "50%",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },

  userBox: {
    display: "flex",
    alignItems: "center",
    gap: "8px",
  },

  avatar: {
    width: "32px",
    height: "32px",
    borderRadius: "50%",
    background: "#3B5BDB",
    color: "white",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    fontWeight: "bold",
  },

  smallText: {
    fontSize: "11px",
    color: "#999",
  },

  username: {
    fontSize: "13px",
    fontWeight: "bold",
  },

  mainContainer: {
    marginLeft: "220px",
    flex: 1,
    display: "flex",
    flexDirection: "column",
    minHeight: "100vh",
  },

  main: {
    marginTop: "60px",
    padding: "25px",
    flex: 1,
  },
};
